{!REQUIRESCRIPT("/soap/ajax/21.0/connection.js")} 

var thisOpportunity= new sforce.SObject("Opportunity"); 

thisOpportunity.Id = '{!Opportunity.Id}'; 
thisOpportunity.FlagToClickCalculateActuals__c= true; 

var saveResults = sforce.connection.update([thisOpportunity]); 

if(saveResults[0].success == 'false'){ 
alert('an error occured: ' + saveResults[0].errors.message); 
} else{
 window.location.href = '/{!Opportunity.Id}';
}
